import{P as u,I as c,g as d,j as m,d as i,k as r,F as b,N as z,x as _,V as p,l as v,ae as w,b as C,M as h,c as M}from"./chunks/framework.CjoWWfVe.js";const B={class:"custom-section section-dark-1 showcase-section-visible"},j={class:"section-container"},V={class:"showcase-interactive"},q={class:"showcase-nav"},F=["onClick"],A={class:"tab-content"},O={class:"tab-title"},S={class:"tab-desc"},T={class:"showcase-display"},P={class:"window-header"},I={class:"window-title"},G={class:"window-body"},H=["src","alt"],D=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ОмниКрафт ЕРП","text":"Порядок в бизнесе. Контроль личного капитала.","tagline":"Программа учёта для индивидуальных мастеров, ремесленных мастерских и других производств. Гибко адаптируется под ваши задачи: ведите учёт бизнесов, личных финансов и жизненных целей. Используйте удобный смешанный учёт без разделения личных и рабочих денег — без рутины лишних переводов. Или закрепите за каждым проектом свои счета для классического раздельного контроля.","image":{"src":"/logo.svg","alt":"Логотип ОмниКрафт ЕРП"},"actions":[{"theme":"brand","text":"Скачать бесплатно (Windows) ↓","link":"https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe"},{"theme":"alt","text":"Читать документацию →","link":"/ru/docs/introduction"}]}},"headers":[],"relativePath":"ru/index.md","filePath":"ru/index.md"}'),R={name:"ru/index.md"},W=Object.assign(R,{setup(N){const o=h(!1),g=h(0),k=M(()=>t.map(a=>({image:a.image,title:a.title,description:a.desc}))),f=a=>{g.value=a,o.value=!0},e=h(0),t=[{title:"Мастерская",desc:"Учёт оборудования, инструментов и расчёт их износа (амортизации).",image:"/ru/dark/workshop.webp"},{title:"Склад сырья",desc:"Партионный учёт материалов (MAC) и распределение логистики.",image:"/ru/dark/raw_materials.webp"},{title:"Расчёт тиража",desc:"Расчёт себестоимости партии и адекватного дефицита сырья на складе.",image:"/ru/dark/calculator_batch_calculator.webp"},{title:"База рецептов",desc:"Создание технологических карт с калькуляцией затрат и времени.",image:"/ru/dark/calculator_recipe_database.webp"},{title:"Верстак производства",desc:"Управление очередью изготовления с динамическим резервированием сырья.",image:"/ru/dark/production.webp"},{title:"Витрина товаров",desc:"Учёт остатков готовой продукции по FIFO и инвентаризация.",image:"/ru/dark/finished_goods.webp"},{title:"Продажи",desc:"POS-терминал, учёт каналов сбыта, комиссий и стоимости доставки.",image:"/ru/dark/sales.webp"},{title:"Движение денег (ДДС)",desc:"Журнал кассовых потоков, учёт расходов и уплаты налогов.",image:"/ru/dark/cash_flow.webp"},{title:"Капитал (Баланс)",desc:"Управленческий баланс мастерской и чистая стоимость бизнеса.",image:"/ru/dark/capital.webp"},{title:"Амортизация",desc:"KPI, точка безубыточности и маржинальность времени (Time ROI).",image:"/ru/dark/analytics.webp"},{title:"Рабочие пространства",desc:"Ведение независимых бизнесов и глобальный учёт личного капитала.",image:"/ru/dark/spaces.webp"}];return(a,s)=>{const x=u("ImageGallery"),y=u("ClientOnly");return c(),d("div",null,[s[8]||(s[8]=m('<div class="custom-section section-dark-2"><div class="section-container"><div class="section-header audience-section-header"><h2 class="gradient-text">Для кого эта программа</h2></div><div class="audience-grid"><div class="audience-card"><div class="audience-card-header"><div class="audience-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg></div><span class="version-badge basic">Базовая версия</span></div><h3>Учёт только производства</h3><div class="audience-text"><p>Программа идеально подходит для мастеров и цехов, создающих физические продукты — будь то работа с кожей, деревом, керамикой, металлом или абсолютно любое другое ремесло.</p><p>Вы получаете строгий контроль всего производственного цикла: от закупки сырья и автоматического расчёта честной себестоимости изделий до управления очередью заказов на верстаке и складом готовой продукции.</p></div></div><div class="audience-card pro-audience"><div class="pro-glow-bg"></div><div class="audience-card-header audience-card-header-pro"><div class="audience-icon pro-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"></polygon><polyline points="2 17 12 22 22 17"></polyline><polyline points="2 12 12 17 22 12"></polyline></svg></div><span class="version-badge pro">Требуется версия ПРО</span></div><h3 class="audience-pro-title">Комплексный учёт бизнеса и жизни</h3><div class="audience-text audience-pro-text"><p>Для тех, кто ведёт несколько проектов параллельно. Система позволяет создавать отдельные изолированные пространства не только для производства, но и для торговли, оказания услуг, обучения или просто учёта затрат на хобби.</p><p>Здесь же вы можете фиксировать важные личные расходы, планировать направления и ставить цели для личной эффективности. Программа объединит данные всех ваших бизнесов, счетов и имущества в глобальное пространство <strong>«Мой капитал»</strong>, отслеживая изменение вашего богатства в динамике.</p></div></div></div></div></div>',1)),i("div",B,[i("div",j,[s[7]||(s[7]=i("div",{class:"section-header"},[i("h2",{class:"gradient-text"},"Интерфейс в деталях"),i("p",{class:"section-subtitle"},[r("ОмниКрафт ЕРП адаптируется под разные задачи. Давайте посмотрим, как устроен полный цикл учёта "),i("span",{class:"highlight-badge"},[r("на примере пространства для "),i("strong",null,"Производства")]),r(". Выбирайте вкладки для просмотра возможностей системы.")])],-1)),i("div",V,[i("div",q,[(c(),d(b,null,z(t,(l,n)=>i("div",{key:n,class:_(["showcase-tab",{active:e.value===n}]),onClick:E=>e.value=n},[s[2]||(s[2]=i("div",{class:"tab-indicator"},null,-1)),i("div",A,[i("div",O,p(l.title),1),i("div",S,p(l.desc),1)])],10,F)),64))]),i("div",T,[s[6]||(s[6]=i("div",{class:"display-glow"},null,-1)),i("div",{class:"app-window",onClick:s[0]||(s[0]=l=>f(e.value))},[i("div",P,[s[3]||(s[3]=i("div",{class:"dot red"},null,-1)),s[4]||(s[4]=i("div",{class:"dot yellow"},null,-1)),s[5]||(s[5]=i("div",{class:"dot green"},null,-1)),i("div",I,p(t[e.value].title)+" — ОмниКрафт ЕРП",1)]),i("div",G,[v(C,{name:"fade",mode:"out-in"},{default:w(()=>[(c(),d("img",{key:e.value,src:t[e.value].image,alt:t[e.value].title,class:"ui-screenshot"},null,8,H))]),_:1})])])])])])]),v(y,null,{default:w(()=>[v(x,{isOpen:o.value,items:k.value,initialIndex:g.value,onClose:s[1]||(s[1]=l=>o.value=!1)},null,8,["isOpen","items","initialIndex"])]),_:1}),s[9]||(s[9]=m('<div class="custom-section section-dark-1"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Фундаментальные проблемы, которые мы решили</h2><p class="section-subtitle">Независимо от того, ведёте ли вы одну ремесленную мастерскую или управляете несколькими бизнесами, система устраняет главные управленческие ошибки и операционное трение.</p></div><div class="timeline-group"><h3>Автоматизация и устранение рутины</h3><p>Освобождение от ручных расчётов и рутинного ведения таблиц</p></div><div class="zigzag-timeline"><div class="zigzag-row"><div class="zigzag-thesis"><h3>Сквозные операции и защита от ошибок</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><path d="m9 15 2 2 4-4"></path></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>Процесс учёта организован в виде строгого сквозного конвейера. Одно нажатие кнопки завершения этапа автоматически списывает задействованное сырьё, зачисляет готовое изделие на витрину и фиксирует его фактическую себестоимость, надёжно защищая данные от случайных ошибок.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Умное распределение затрат без калькулятора</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#a78bfa" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><rect width="16" height="20" x="4" y="2" rx="2"></rect><line x1="8" x2="16" y1="6" y2="6"></line><line x1="16" x2="16" y1="14" y2="18"></line><path d="M16 10h.01"></path><path d="M12 10h.01"></path><path d="M8 10h.01"></path><path d="M12 14h.01"></path><path d="M8 14h.01"></path><path d="M12 18h.01"></path><path d="M8 18h.01"></path></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>Вам не нужно быть бухгалтером. Программа сама рассчитывает скользящую среднюю стоимость материалов (МАК) при каждой новой закупке и автоматически распределяет стоимость логистики, а также помогает оценить износ оборудования (от ручного инструмента до муфельной печи или ЧПУ-станка) для точного планирования накладных расходов.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Конец сюрпризам на верстаке</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#fb923c" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="m7.5 4.27 9 5.15"></path><path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z"></path><path d="m3.3 7 8.7 5 8.7-5"></path><path d="M12 22V12"></path></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>Вы увидите предупреждение о дефиците материалов ещё до того, как приступите к заказу или возьмёте предоплату. Динамическая очередь автоматически резервирует на складе нужную фурнитуру, древесину или специфическую химию в зависимости от приоритета задачи.</p></div></div></div><div class="timeline-group"><h3>Честные финансы и наглядная аналитика</h3><p>Эффективный и лёгкий контроль</p></div><div class="zigzag-timeline"><div class="zigzag-row"><div class="zigzag-thesis"><h3>Исключение «иллюзии прибыли»</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#f87171" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>Разница между ценой продажи и стоимостью основного материала — это не чистая прибыль. Калькулятор поможет объединить все издержки: сырьё, накладные расходы (амортизацию оборудования, аренду, расходные материалы), процент брака и цену ваших рабочих часов, показав реальную, честную чистую прибыль каждого изделия.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Чистая прибыль за час работы</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#34d399" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>Рейтинг изделий по чистой прибыли в час наглядно покажет, что серийное изготовление свечей приносит 1 800 ₽/ч, а создание сложного украшения по индивидуальному заказу — всего 400 ₽/ч. Это точный математический сигнал для пересмотра цен или оптимизации вашего ассортимента.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Сфокусированная бизнес-аналитика</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#38bdf8" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><line x1="12" x2="12" y1="20" y2="10"></line><line x1="18" x2="18" y1="20" y2="4"></line><line x1="6" x2="6" y1="20" y2="16"></line></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>Вам доступна глубокая детализированная аналитика. Программа предоставляет общую аналитику и полезные данные на отдельных рабочих вкладках. Каждый показатель имеет логическую ценность, охватывая как ключевые, так и важные дополнительные параметры вашего дела, исключая бессистемные данные, чтобы не превратить аналитику в хаос.</p></div></div><div class="zigzag-row"><div class="zigzag-thesis"><h3>Защита старых партий от обесценивания</h3><span class="thesis-icon"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="#facc15" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2H2v10l9.29 9.29c.94.94 2.48.94 3.42 0l6.58-6.58c.94-.94.94-2.48 0-3.42L12 2Z"></path><path d="M7 7h.01"></path></svg></span></div><div class="zigzag-dot"></div><div class="zigzag-content"><p>Даже если завтра поставщики поднимут цены на сырьё в два раза, программа спишет проданное старое изделие с полки по его первоначальной, исторически верной себестоимости (метод ФИФО). Ваша прибыль в финансовых отчетах всегда будет посчитана с ювелирной точностью.</p></div></div></div><div class="timeline-footer"><h3>И многое другое...</h3><p>Возможности OmniCraft ERP выходят за рамки простого производственного учёта. Система позволяет проводить инвентаризацию сырья и изделий без искажения отчётов о движении денежных средств (ДДС), распределять расходы на логистику (выбирая между оплатой клиентом и уменьшением прибыли мастерской), гибко настраивать цены под разные каналы продаж и вести структурированный реестр операций ДДС для расчёта налогов и прочего.</p></div></div></div><div class="custom-section section-dark-2 pro-section"><div class="section-container"><div class="section-header"><span class="pro-kicker">✨ Экосистема ПРО</span><h2 class="pro-heading">А что за рамками Производства?</h2><p class="section-subtitle">Базовая версия <strong>«Стандарт»</strong> идеально закрывает нужды одного ремесленного дела. Но если вы мыслите как предприниматель, версия <strong>ПРО</strong> позволит вам развернуть отдельные независимые пространства под каждое направление и объединить их в глобальный капитал.</p></div><div class="bento-grid profiles-grid mb-12"><div class="bento-card profile-card active-profile"><div class="profile-icon-wrapper icon-blue"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M2 20a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V8l-7 5V8l-7 5V4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2Z"></path><path d="M17 18h1"></path><path d="M12 18h1"></path><path d="M7 18h1"></path></svg></div><h3>Производство</h3><p>Полный цикл: закупка сырья (МАК), калькуляция, верстак, резервирование материалов и склад готовой продукции.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-purple"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"></path></svg></div><h3>Услуги / Кастом <span class="coming-soon-badge">Скоро</span></h3><p>Для индивидуальных заказов, реставрации или дизайна. Учёт вашего затраченного времени без привязки к жёсткому складу витрины.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-orange"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9h18v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V9Z"></path><path d="m3 9 2.45-4.9A2 2 0 0 1 7.24 3h9.52a2 2 0 0 1 1.8 1.1L21 9"></path><path d="M12 3v6"></path></svg></div><h3>Торговля / Ритейл <span class="coming-soon-badge">Скоро</span></h3><p>Прямые закупки и перепродажа готовых товаров, инструментов или химии. Учёт оптовых партий без производственного конвейера.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-pink"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect width="20" height="14" x="2" y="3" rx="2"></rect><line x1="8" x2="16" y1="21" y2="21"></line><line x1="12" x2="12" y1="17" y2="21"></line></svg></div><h3>Обучение / Цифровые товары <span class="coming-soon-badge">Скоро</span></h3><p>Продажа авторских электронных лекал, видеоуроков или проведение живых мастер-классов. Чистая маржа без физического сырья.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-teal"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="13.5" cy="6.5" r=".5" fill="currentColor"></circle><circle cx="17.5" cy="10.5" r=".5" fill="currentColor"></circle><circle cx="8.5" cy="7.5" r=".5" fill="currentColor"></circle><circle cx="6.5" cy="12.5" r=".5" fill="currentColor"></circle><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.926 0 1.648-.746 1.648-1.688 0-.437-.18-.835-.437-1.125-.29-.289-.438-.652-.438-1.125a1.64 1.64 0 0 1 1.668-1.668h1.996c3.051 0 5.555-2.503 5.555-5.554C21.965 6.012 17.461 2 12 2z"></path></svg></div><h3>Деятельность / Хобби <span class="coming-soon-badge">Скоро</span></h3><p>Песочница для увлечений (керамика, садоводство). Фиксируйте расходы на материалы просто чтобы понимать, во сколько обходится хобби.</p></div><div class="bento-card profile-card"><div class="profile-icon-wrapper icon-red"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><circle cx="12" cy="12" r="6"></circle><circle cx="12" cy="12" r="2"></circle></svg></div><h3>ЖНЦ (Цели) <span class="coming-soon-badge">Скоро</span></h3><p>Пространство Желаний, Направлений и Целей. Планируйте крупные покупки или ставьте нефинансовые цели для личного развития и эффективности.</p></div></div><div class="bento-grid pro-grid"><div class="bento-card span-full capital-card"><div class="capital-glow"></div><div class="capital-content capital-content-flex"><div class="capital-text-block"><div class="profile-icon-wrapper icon-green large-icon"><svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"></rect><line x1="2" y1="10" x2="22" y2="10"></line></svg></div><h3 class="capital-title">Глобальный дашборд<br>«Мой капитал»</h3><p class="capital-desc"> Настоящая магия ПРО-режима. Программа автоматически собирает чистую прибыль со всех ваших бизнесов, прибавляет стоимость активов (квартиры, машины) и актуальные остатки на личных банковских картах. </p></div><div class="capital-feature-card"><div class="capital-feature-glow"></div><h4 class="capital-feature-title"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#10B981" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="m9 12 2 2 4-4"></path></svg> Свобода от рутины чеков </h4><p class="capital-feature-desc"> Вам больше не нужно вбивать в таблицу каждую чашку кофе или покупку продуктов! Сопоставляя внесенные доходы, крупные расходы и фактические остатки на картах, система сама выведет чистое сальдо неучтённых повседневных операций. Это освобождает от микроменеджмента, показывая реальный баланс ваших мелких бытовых расходов и случайных приходов. </p></div></div></div><div class="bento-card span-full modules-banner"><div class="profile-icon-wrapper icon-blue medium-icon"><svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><path d="M20.5 11H19V7c0-1.1-.9-2-2-2h-4V3.5C13 2.12 11.88 1 10.5 1S8 2.12 8 3.5V5H4c-1.1 0-1.99.9-1.99 2v3.8H3.5c1.49 0 2.7 1.21 2.7 2.7s-1.21 2.7-2.7 2.7H2V20c0 1.1.9 2 2 2h3.8v-1.5c0-1.49 1.21-2.7 2.7-2.7 1.49 0 2.7 1.21 2.7 2.7V22H17c1.1 0 2-.9 2-2v-4h1.5c1.38 0 2.5-1.12 2.5-2.5S21.88 11 20.5 11z"></path></svg></div><div><h4 class="modules-title">Сквозные модули (Скоро)</h4><p class="modules-desc">В будущих обновлениях экосистема будет расширяться за счет подключаемых плагинов (например, <strong>модуля генерации параметрических выкроек для кожевников</strong>). Вы сможете добавлять в систему только те инструменты, которые нужны для решения ваших конкретных производственных задач. Модули доступны как в базовой, так и в версии ПРО.</p></div></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="mixed-finance-banner"><div class="mixed-finance-glow left"></div><div class="mixed-finance-glow right"></div><div class="mixed-finance-content"><div class="mixed-finance-header"><div class="mixed-finance-icon"><svg width="52" height="52" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" class="mixed-finance-svg"><defs><linearGradient id="mixGrad1" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#3B82F6"></stop><stop offset="100%" stop-color="#2563EB"></stop></linearGradient><linearGradient id="mixGrad2" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#A594FD"></stop><stop offset="100%" stop-color="#7B61FF"></stop></linearGradient></defs><circle cx="8.5" cy="12" r="6.5" stroke="url(#mixGrad1)" stroke-width="2" fill="rgba(59, 130, 246, 0.15)"></circle><circle cx="15.5" cy="12" r="6.5" stroke="url(#mixGrad2)" stroke-width="2" fill="rgba(165, 148, 253, 0.15)"></circle><polyline points="3 16 9 10 13 13 21 5" stroke="#FFFFFF" stroke-width="2"></polyline><polyline points="17 5 21 5 21 9" stroke="#FFFFFF" stroke-width="2"></polyline></svg></div><div><h2 class="mixed-finance-title"> Учёт без лишней бюрократии:<br><span class="mixed-finance-highlight">Смешанные финансы</span></h2></div></div><div class="mixed-finance-text-wrapper"><p class="mixed-finance-text"> По умолчанию ОмниКрафт ЕРП спроектирован так, чтобы не усложнять вам жизнь. Вам <strong>не нужно заводить отдельный банковский счёт для бизнеса</strong> или делать искусственные переводы самому себе «на жизнь». Оплачивайте материалы с личной карты, а выручку тратьте на бытовые нужды — система всё равно покажет кристально чистую и точную картину. </p></div><div class="mixed-finance-cards"><div class="mixed-finance-card"><h4 class="mixed-finance-card-title red"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg> Сальдо ДДС </h4><p class="mixed-finance-card-desc">Покажет, какую сумму личных средств вы вложили на старте и <strong>насколько уже окупился ваш бизнес</strong>.</p></div><div class="mixed-finance-card"><h4 class="mixed-finance-card-title green"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"></polyline><polyline points="16 7 22 7 22 13"></polyline></svg> Чистая прибыль </h4><p class="mixed-finance-card-desc">Отразит реальную <strong>эффективность деятельности</strong> вашей мастерской, независимо от того, где физически лежат деньги.</p></div><div class="mixed-finance-card"><h4 class="mixed-finance-card-title blue"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg> Капитал </h4><p class="mixed-finance-card-desc">Оценит <strong>текущую стоимость бизнеса</strong>, аккуратно суммируя всё ваше оборудование, сырьё и готовые изделия.</p></div></div><div class="mixed-finance-note"><p class="mixed-finance-note-text"><strong>Гибкость системы:</strong> Если со временем вы решите полностью разделить личные и бизнес-финансы, вам не придётся менять программу. В любой момент вы можете просто завести под мастерскую отдельный счёт, и система бесшовно поддержит классический раздельный учёт. </p></div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="bento-card span-full docs-banner"><div class="docs-left"><div class="docs-header"><div class="profile-icon-wrapper icon-blue custom-docs-icon"><svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z"></path><path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z"></path></svg></div><h2 class="docs-title">Исчерпывающая документация</h2></div><p class="docs-desc"> ОмниКрафт ЕРП — это не просто табличка, а профессиональный инструмент с глубокой финансовой логикой. Мы детально описали каждый механизм системы, чтобы вы могли использовать её потенциал на 100%. <br><br> Узнайте, как работает производственный конвейер, как методы МАК и ФИФО защищают вашу прибыль, как перенести остатки из старых программ и правильно вести смешанные финансы. </p><a class="vp-button brand docs-btn" href="/ru/docs/introduction"> Читать руководство <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="docs-right"><div class="docs-toc-card"><h4 class="docs-toc-title">Содержание руководства:</h4><ul class="docs-toc-list"><li class="docs-toc-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="docs-toc-icon"><path d="M12 2S4.5 6 4.5 14.5c0 2 1 3.5 3 4.5V22l4.5-2 4.5 2v-3c2-1 3-2.5 3-4.5C19.5 6 12 2 12 2z"></path><circle cx="12" cy="11" r="2"></circle></svg><a href="/ru/docs/getting-started" class="docs-toc-link">Быстрый старт и перенос остатков</a></li><li class="docs-toc-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="docs-toc-icon"><path d="M17 1l4 4-4 4"></path><path d="M3 11V9a4 4 0 0 1 4-4h14"></path><path d="M7 23l-4-4 4-4"></path><path d="M21 13v2a4 4 0 0 1-4 4H3"></path></svg><a href="/ru/docs/accounting-logic" class="docs-toc-link">Логика учёта: Конвейер производства</a></li><li class="docs-toc-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="docs-toc-icon"><path d="M2 4l3 12h14l3-12-6 6-4-6-6 6-4-6z"></path><rect x="3" y="18" width="18" height="2" rx="1"></rect></svg><a href="/ru/docs/spaces/moy-kapital/pro-mode" class="docs-toc-link">ПРО-режим: Личные финансы</a></li><li class="docs-toc-item"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="docs-toc-icon"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg><a href="/ru/docs/backups" class="docs-toc-link">Бэкапы и защита (GFS, WAL)</a></li></ul></div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Прозрачная модель лицензирования</h2><p class="section-subtitle">Никаких скрытых платежей. Платите только за тот масштаб, который вам нужен.</p></div><div class="sleek-pricing"><div class="pricing-card"><div class="p-header"><h4>Бесплатная (Пробная)</h4><p>Для старта и тестов</p></div><div class="p-price"><div class="price-row"><span class="price-val">0 ₽</span></div></div><ul class="p-features"><li><i></i>Все возможности лицензии «Стандартная»</li><li class="warning"><i></i>Лимит: до 20 чеков (продаж)</li><li class="disabled"><i></i>Дополнительные модули недоступны</li></ul></div><div class="pricing-card standard"><div class="p-header"><h4>Standard (Стандартная)</h4><p>Основной инструмент мастера</p></div><div class="p-price"><div class="price-row"><span class="price-val">190 ₽</span><span class="price-period">/ мес</span></div><div class="price-or">или</div><div class="price-row"><span class="price-val">4 990 ₽</span><span class="price-period">бессрочно</span></div></div><ul class="p-features"><li class="active"><i></i><strong>Весь функционал для учёта производства</strong></li><li><i></i>Снятие лимита: безграничные продажи</li><li><i></i>Два вида: подписка или вечная лицензия</li><li><i></i>Доступны модули расширения (докупка)</li><li><i></i>Возможность перехода на лицензию «ПРО»</li></ul></div><div class="pricing-card pro-card pricing-card-bg-pad"><div class="pro-glow"></div><div class="pro-badge">ПРО-РЕЖИМ</div><div class="p-header pro-header"><h4>PRO (ПРО-расширение)</h4><p>Комплексный учёт бизнеса и личных средств</p></div><div class="p-price"><div class="price-row"><span class="price-val">3 990 ₽</span><span class="price-period">бессрочно</span></div></div><ul class="p-features pro-features"><li class="active-pro"><i></i><strong>Все возможности лицензии «Стандартная»</strong></li><li class="active-pro"><i></i><strong>Мультипространства (разные бизнесы)</strong></li><li class="active-pro"><i></i><strong>Общее пространство «Мой капитал»</strong></li><li><i></i>Доступны модули расширения (докупка)</li><li><i></i>Разовая оплата (переход с лицензии «Стандартная»)</li></ul></div></div><div class="pricing-pre-notice"><p><strong>Важное примечание о лицензии ПРО:</strong> Для полноценной работы программы требуется активная лицензия Стандарт (ежемесячная подписка или единоразовая покупка на неограниченное время), после чего можно расширить программу до версии ПРО. Версия ПРО будет работать только при наличии активированной лицензии Стандарт (не важно какой именно — подписочной или бессрочной).</p><p><strong>Использование на устройствах:</strong> Коммерческую лицензию можно одновременно использовать на 5-ти устройствах. Список активных устройств можно гибко редактировать на <a href="/ru/docs/buy-license">странице приобретения лицензии</a> (с помощью простой формы управления). В случае выхода устройства из строя, вы можете легко удалить его из списка и привязать новое.</p></div><div class="pricing-action-wrapper"><a class="vp-button brand pricing-action-btn" href="/ru/docs/buy-license"> Купить (или расширить) лицензию </a></div><div class="pricing-notice with-margin"><strong>Специализированные дополнения (модули):</strong> Нишевые инструменты под конкретные задачи оплачиваются единоразово и отдельно. Вы не переплачиваете за функции, которыми не пользуетесь. Модули доступны для Стандартной и ПРО лицензий. </div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Часто задаваемые вопросы</h2></div><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Я веду учёт в Экселе. Сложно ли перейти на ОмниКрафт ЕРП?</summary><div class="faq-content"><p>Переход занимает минимум времени. Вам не нужно переносить всю историю старых продаж. Достаточно использовать подход «оценочной точки старта»: внесите ваше текущее оборудование в Мастерскую, <strong>обязательно отметив его как «Безвозмездное поступление»</strong> (чтобы программа не списала средства из ДДС повторно, ведь эти затраты уже были учтены вами в прошлом), добавьте фактические остатки материалов на Склад сырья и проведите специальную стартовую корректирующую операцию для фиксации исторического сальдо ДДС и долгов. Подробнее о переносе читайте в разделе <a class="faq-link" href="/ru/docs/getting-started">Быстрый старт</a>.</p></div></details><details class="faq-item"><summary class="faq-summary">Что будет, если мой компьютер сломается?</summary><div class="faq-content"><p>Встроенные теневые копии (ГФС) защищают данные от внезапных сбоев питания, но при физической поломке диска они погибнут вместе с ним. Поэтому мы настоятельно рекомендуем регулярно экспортировать базу данных вручную на флешку или в облако. При переносе на новый ПК установите программу и импортируйте сохранённый файл. Лицензию потребуется восстановить на специальной странице управления лицензиями на сайте: так как она привязывается к оборудованию, вам нужно будет сбросить старую привязку, введя ваш лицензионный токен. Лицензионный ключ поддерживает одновременное использование <strong>не более чем на 5 устройствах</strong>, и вы можете самостоятельно удалять старые устройства из списка и привязывать новые.</p></div></details><details class="faq-item"><summary class="faq-summary">Есть ли версия для Mac OS, Linux или Android?</summary><div class="faq-content"><p>В данный момент официальные установочные пакеты собираются только под ОС Windows. Однако ядро системы спроектировано как полностью кроссплатформенное. Разработка и релиз нативных версий программы для Mac OS, Linux, а также мобильного приложения для Android планируются в будущих обновлениях.</p></div></details><details class="faq-item"><summary class="faq-summary">Могу ли я работать с базой с разных компьютеров?</summary><div class="faq-content"><p>ОмниКрафт ЕРП спроектирована как локальная автономная система для максимальной защиты коммерческой тайны, прямой онлайн-синхронизации в ней сейчас нет. В будущем планируется реализация полноценной облачной синхронизации данных для бесшовной совместной работы на разных устройствах.</p></div></details><details class="faq-item"><summary class="faq-summary">Что произойдёт, когда закончится лимит в 20 продаж в бесплатной версии?</summary><div class="faq-content"><p>Программа заблокирует проведение продаж. При этом все остальные возможности остаются полностью доступными: вы можете свободно добавлять новые материалы, вносить инструменты и станки в Мастерскую, создавать или редактировать рецепты, наполнять справочники и анализировать прошлые периоды. После активации приобретенного лицензионного ключа все ограничения снимутся мгновенно, а накопленная история останется в целости.</p></div></details><details class="faq-item"><summary class="faq-summary">Можно ли вести учёт нескольких разных проектов в одной программе?</summary><div class="faq-content"><p>В рамках лицензии «Стандартная» весь учёт ведётся в рамках одного производства. Если у вас несколько направлений (например, кожевенное производство и отдельный магазин фурнитуры), вам потребуется расширить программу до лицензии «ПРО». Он позволяет создавать изолированные «Мультипространства» с раздельными складами и ДДС, объединяя их итоговую прибыль в глобальном пространстве «Мой капитал».</p></div></details><details class="faq-item"><summary class="faq-summary">Нужно ли платить за обновления программы при покупке вечной лицензии?</summary><div class="faq-content"><p>Нет, при покупке бессрочной вечной лицензии все последующие системные обновления, улучшения интерфейса и исправления ошибок в рамках вашего тарифа предоставляются абсолютно бесплатно. Встроенный автоапдейтер сам предложит установить новую версию и выполнит миграцию вашей базы данных. Отдельно оплачиваются только переход до версии ПРО и специализированные подключаемые модули.</p></div></details></div></div></div><div class="custom-cta-block cta-centered"><div class="cta-icon-wrapper"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3c-1.2 0-3.5.5-5 1.5C5 5.8 4 8 4 10.5c0 3 1.5 6.5 4 8.5l4 2 4-2c2.5-2 4-5.5 4-8.5 0-2.5-1-4.7-3-6C15.5 3.5 13.2 3 12 3z" stroke="var(--vp-c-brand)"></path><path d="M7 14s2-3 5-3 5 3 5 3" stroke="#A594FD"></path><path d="M12 7V17M12 7L9 11M12 7l3 4" stroke="var(--vp-c-brand)"></path></svg></div><h2 class="gradient-text cta-title">Спроектировано в мастерской.<br>Создано для мастеров с бизнес-мышлением.</h2><p class="cta-text"> Эта программа рождена не в безликих офисах, а на реальном верстаке нашей кожевенной мастерской. Каждый её алгоритм — от каскадных резервов материалов до амортизации оборудования — спроектирован на основе личного ремесленного опыта. Мы изнутри знаем все тонкости производства и повседневные боли мастера. </p><div class="cta-buttons cta-buttons-spaced"><a class="vp-button brand" href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe">⬇ Скачать бесплатно (Windows)</a><a class="vp-button alt" href="/ru/docs/introduction">Читать документацию</a></div><div class="footer-links"><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank">Репозиторий проекта</a><a href="/ru/docs/terms#payment-delivery-returns">Оплата, доставка и возврат</a><a href="/ru/docs/about">О разработчике</a><a href="/ru/docs/contacts">Контакты и Реквизиты</a></div><div style="margin-top:1.5rem;font-size:0.9rem;color:var(--vp-c-text-2);line-height:1.5;text-align:center;"> Мурашкин Николай Валерьевич<br> ИНН 232904256501 </div></div>',7))])}}});export{D as __pageData,W as default};
